AI","Zen G explains and navigates; it does not claim spiritual authority."]].map(([a,b])=><article className="rounded-2xl border p-6" key={a}><h3 className="font-bold text-[#7c2d12]">{a}</h3><p className="mt-3 text-stone-600">{b}</p></article>)}</div><Link className="mt-10 inline-block rounded-xl bg-[#7c2d12] px-6 py-3 font-bold text-white" href="/services">Explore our services</Link></div></section><LeadershipGovernanceSection /></main>}

