"use client";
import Link from "next/link";import { useEffect,useState } from "react";import { usePathname } from "next/navigation";import { getPublicService,getPublicServices } from "@/services/service-catalog.api";import type { CatalogService } from "@/types/service-catalog";
export function BusinessServiceDetail(){const slug=decodeURIComponent(usePathname().split("/").pop()||"");const [service,setService]=useState<CatalogService|null>(null);const [related,setRelated]=useState<CatalogService[]>([]);const [error,setError]=useState("");useEffect(()=>{void getPublicService(slug).then(s=>{setService(s);return getPublicServices({category:s.categorySlug,page:1,pageSize:4})}).then(r=>setRelated(r.items.filter(x=>x.slug!==slug).slice(0,3))).catch(e=>setError(e instanceof Error?e.message:"Service not found."))},[slug]);if(error)return <main className="grid min-h-[60vh] place-items-center text-center"><div><h1 className="text-3xl font-bold">Service unavailable</h1><p className="mt-3 text-red-700">{error}</p><Link className="mt-5 inline-block text-orange-800" href="/services">Return to services</Link></div></main>;if(!service)return <main className="grid min-h-[60vh] place-items-center" role="status">Loading service…</main>;const enquire=service.workflowKey?.startsWith("PITRU_MOKSHA_")?"/services":"/contact";return <main className="min-h-screen bg-[#fffaf0]"><section className="bg-gradient-to-br from-stone-950 to-[#7c2d12] px-6 py-16 text-white"><div className="mx-auto max-w-6xl"><Link className="text-orange-200" href="/services"> All services</Link><p className="mt-8 text-sm font-bold uppercase tracking-widest text-orange-200">{service.categoryName}</p><h1 className="mt-3 text-4xl font-bold sm:text-6xl">{service.name}</h1><p className="mt-5 max-w-3xl text-lg text-orange-50">{service.shortDescription}</p></div></section><section className="mx-auto grid max-w-6xl gap-8 px-6 py-12 md:grid-cols-3"><article className="space-y-8 rounded-2xl bg-white p-7 shadow md:col-span-2"><div><h2 className="text-2xl font-bold">Purpose and description</h2><p className="mt-3 whitespace-pre-wrap text-stone-700">{service.description||"Our coordinator will explain the complete service plan during review."}</p></div><div><h2 className="text-xl font-bold">Who it is for</h2><p className="mt-3 whitespace-pre-wrap text-stone-700">{service.eligibility||"A qualified religious partner will review your family requirements before confirmation."}</p></div><div><h2 className="text-xl font-bold">Required materials</h2><p className="mt-3 whitespace-pre-wrap text-stone-700">{service.requiredMaterials||"Materials and preparation will be confirmed after human review."}</p></div><div><h2 className="text-xl font-bold">How coordination works</h2><ol className="mt-3 list-decimal space-y-2 pl-5 text-stone-700"><li>Submit your requirements privately.</li><li>Our team and a qualified partner review the request.</li><li>Dates, materials, pricing, and travel needs are confirmed before service.</li></ol></div></article><aside className="h-fit rounded-2xl bg-white p-7 shadow"><p className="text-sm text-stone-500">Pricing</p><p className="mt-1 text-2xl font-bold">{service.priceMinor?new Intl.NumberFormat("en-IN",{style:"currency",currency:service.currency}).format(service.priceMinor/100):"On enquiry"}</p><p className="mt-5 text-sm text-stone-500">Expected duration</p><p className="font-semibold">{service.durationMinutes?`${service.durationMinutes} minutes`:"Confirmed after review"}</p><Link className="mt-7 block rounded-xl bg-[#9a3412] px-5 py-3 text-center font-bold text-white" href={enquire}>Enquire about this service</Link><Link className="mt-3 block rounded-xl border px-5 py-3 text-center" href="/travel-assistance">Travel assistance</Link></aside></section>{related.length?<section className="mx-auto max-w-6xl px-6 pb-16"><h2 className="text-2xl font-bold">Related services</h2><div className="mt-5 grid gap-4 md:grid-cols-3">{related.map(x=><Link className="rounded-xl bg-white p-5 shadow-sm" href={`/services/${x.slug}`} key={x.id}><h3 className="font-bold">{x.name}</h3><p className="mt-2 text-sm text-stone-600">{x.shortDescription}</p></Link>)}</div></section>:null}</main>}

